-- SHINDORA STREAM CLOUDFLARE D1 FULL DATABASE IMPORT (271+ VIDEOS & SETTINGS)

CREATE TABLE IF NOT EXISTS links (
    id TEXT PRIMARY KEY,
    title TEXT,
    slug TEXT UNIQUE,
    originalUrl TEXT,
    posterUrl TEXT,
    sources TEXT,
    hostType TEXT,
    createdAt TEXT,
    updatedAt TEXT,
    subtitles TEXT,
    type TEXT,
    embedUrl TEXT
);

CREATE INDEX IF NOT EXISTS idx_links_slug ON links(slug);
CREATE INDEX IF NOT EXISTS idx_links_updatedAt ON links(updatedAt);

CREATE TABLE IF NOT EXISTS settings (
    id TEXT PRIMARY KEY,
    type TEXT UNIQUE,
    username TEXT,
    password TEXT,
    publicKey TEXT,
    privateKey TEXT,
    urlEndpoint TEXT,
    playerType TEXT,
    autoplay INTEGER,
    vastEnabled INTEGER,
    vastTags TEXT,
    cdnUrl TEXT,
    youtubeApiKey TEXT,
    vkApiKey TEXT,
    vkServiceToken TEXT,
    isAdblockEnabled INTEGER,
    downloadCdnUrl TEXT,
    isCustomDownloadCdnEnabled INTEGER
);

CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    token TEXT UNIQUE,
    username TEXT,
    expiresAt TEXT,
    refreshToken TEXT,
    refreshExpiresAt TEXT,
    createdAt TEXT,
    updatedAt TEXT
);

CREATE INDEX IF NOT EXISTS idx_sessions_refresh ON sessions(refreshToken);

